#pragma once
#include <stddef.h>
#include <stdint.h>

/* Original Keccak-256 (0x01 padding), as used by Ethereum and Monero's cn_fast_hash. NOT NIST SHA3-256. */
void keccak256(const uint8_t *msg, size_t len, uint8_t out[32]);
/* The Keccak-f[1600] permutation on 25 little-endian 64 bit lanes (Merlin / STROBE build on it). Straight-line code on 32 bit
 * word pairs (keccak_fast.c, generated by tools/gen_keccak_fast.py): about 5 times faster than compact loops on the PSX CPU.
 * Little endian machines only. */
void keccak_f1600(uint64_t st[25]);
